import { ConfigUrl } from '../../../../configs/url'

export const ELEARNING_ACTIONS = {
  DETAIL_PAGE_ENABLE_REQUEST: 'DETAIL_PAGE_ENABLE_REQUEST',
  DETAIL_PAGE_ENABLE: 'DETAIL_PAGE_ENABLE',

  GET_PARTNER_TOKEN_REQUEST: 'GET_PARTNER_TOKEN_REQUEST',
  GET_PARTNER_TOKEN: 'GET_PARTNER_TOKEN'
}

export const enableDetailPage = (payload) => ({
  type: ELEARNING_ACTIONS.DETAIL_PAGE_ENABLE_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.elearningDetailPageEnableApi
  }
})

export const getPartnerToken = (payload) => ({
  type: ELEARNING_ACTIONS.GET_PARTNER_TOKEN_REQUEST,
  payload: {
    ...payload,
    method: 'post', // 'authGet',
    url: ConfigUrl.getPartnerTokenApi(payload.partner_code)
  }
})
