import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useElearningIntroContextValue } from '../../context'
import { enableDetailPage, getPartnerToken } from '../actions'

export const useElearningIntroServiceCall = (actionsCall = () => {}) => {
  const [elearningIntroState, dispatch] = useElearningIntroContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [elearningIntroState, request]
}

export const useEnableDetailPage = () => {
  return useElearningIntroServiceCall(enableDetailPage)
}

export const useGetPartnerToken = () => {
  return useElearningIntroServiceCall(getPartnerToken)
}
