import { Container, CustomText } from '../../../../components'
import { ELearningWrapper } from './index.style'
import { LANG_STRINGS } from '../../../../lang'
import ButtonWithIcon from '../../../../components/ButtonWithIcon'
import React, { useCallback, useState, useEffect, useRef } from 'react'
import { BottomActionContainerStyle, Row } from '../../../../commonStyle/index.style'
import { SEND_GOLD_ICON, ELEARNING_BACKGROUND } from '../../../../images/imageUrl'
import CustomCheckbox from '../../../../components/CustomCheckbox'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { get } from 'lodash'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useEnableDetailPage, useGetPartnerToken } from '../state/hooks/useElearningIntroState'
import { useGlobalContextValue } from '../../../../contextProvider/GlobalContext'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { PARTNER_CODE } from '../../../../constants/appConstants'

function ElearningIntro (props) {
  const eLearningPara1 = 'Platform e-learning terbaru dari kami yang akan memudahkan Anda sebagai mitra dalam menjalankan bisnis asuransi di PasarPolis Mitra, mulai dari panduan penjualan hingga cara mencapai target GWP. PasarPolis Mitra LMS merupakan sebuah platform e-learning yang berisi materi pembelajaran online untuk memenuhi kebutuhan penjualan asuransi para mitra. Platform ini tentunya dapat membantu mitra memahami lebih dalam mulai dari pengetahuan produk hingga sales pitching!'
  const eLearningListHead = 'Materi yang akan Anda dapatkan'
  const eLearningList = [
    'Pengenalan masing-masing produk PasarPolis Mitra.',
    'Hal-hal teknis yang akan Anda alami dalam proses penjualan asuransi PasarPolis Mitra.',
    'Materi pembelajaran yang akan Anda dapatkan bisa berupa video, materi teks. Lalu, di akhir setiap level akan ada kuis untuk naik ke level selanjutnya.'
  ]
  const eLearningPara3 = 'Materi pembelajaran yang akan Anda dapatkan bisa berupa video, materi teks. Lalu, di akhir setiap level akan ada kuis untuk naik ke level selanjutnya.'
  const [isCheckboxSelected, setIsCheckboxSelected] = useState(false)
  const [showLoader, setShowLoader] = useState(false)
  const [{ getAgentDetailData }] = useGlobalContextValue()

  const [{
    DETAIL_PAGE_ENABLE_LOADER, GET_PARTNER_TOKEN_LOADER
  }] = useLoaderContextValue()
  const [
    {
      DETAIL_PAGE_ENABLE_ERROR, detailPageEnableStatus, GET_PARTNER_TOKEN_ERROR, getPartnerTokenStatus
    },
    dispatchError] = useErrorContextValue()
  const [, enableDetailPage] = useEnableDetailPage()
  const [getPartnerTokenData, getPartnerTokenRequest] = useGetPartnerToken()

  const accessToken = get(getPartnerTokenData, 'getPartnerTokenData.access_token', '')
  const prosparkUrl = `${process.env.REACT_APP_ELMS_URL}?access_token=${accessToken}`

  const that = useRef({ isTokenCall: false })
  useEffect(() => {
    if (!that.current.isTokenCall) {
      getPartnerTokenRequest({ partner_code: PARTNER_CODE.PROSPARK })
      that.current.isTokenCall = true
    }
  }, [getPartnerTokenRequest])

  useEffect(() => {
    if (GET_PARTNER_TOKEN_ERROR && getPartnerTokenStatus) {
      NotificationManager.error(getPartnerTokenStatus)
      dispatchError(resetError({
        getPartnerTokenStatus: '',
        GET_PARTNER_TOKEN_ERROR: false
      }))
    }
  }, [getPartnerTokenStatus, dispatchError, GET_PARTNER_TOKEN_ERROR])

  const redirToProspark = useCallback(() => {
    setShowLoader(true)
    if (accessToken) {
      window.open(prosparkUrl, '_self')
      setShowLoader(false)
    } else {
      setShowLoader(false)
    }
  }, [prosparkUrl, accessToken, setShowLoader])

  useEffect(() => {
    if ((detailPageEnableStatus === 'success') || (getPartnerTokenStatus === 'success' && !(get(getAgentDetailData, 'elearning_details_page_enable', true)))) {
      redirToProspark()
      dispatchError(resetError({
        getPartnerTokenStatus: '',
        GET_PARTNER_TOKEN_ERROR: false
      }))
    } else if (DETAIL_PAGE_ENABLE_ERROR && detailPageEnableStatus) {
      NotificationManager.error(detailPageEnableStatus)
      dispatchError(resetError({
        detailPageEnableStatus: '',
        DETAIL_PAGE_ENABLE_ERROR: false
      }))
    }
  }, [
    detailPageEnableStatus, dispatchError, getAgentDetailData,
    DETAIL_PAGE_ENABLE_ERROR, redirToProspark, getPartnerTokenStatus
  ])

  const handleCourseStart = useCallback(() => {
    if (get(getAgentDetailData, 'elearning_details_page_enable') !== !isCheckboxSelected) {
      enableDetailPage({
        body: {
          elearning_details_page_enable: !isCheckboxSelected
        }
      })
    } else {
      redirToProspark()
    }
  }, [enableDetailPage, isCheckboxSelected, getAgentDetailData, redirToProspark])

  const handleCheckbox = useCallback(() => {
    setIsCheckboxSelected(!isCheckboxSelected)
  }, [isCheckboxSelected, setIsCheckboxSelected])

  return (
    <Container
      title='eLearning'
      showInnerHeader
      loader={DETAIL_PAGE_ENABLE_LOADER || showLoader || GET_PARTNER_TOKEN_LOADER}
    >
      <NotificationContainer />
      {!DETAIL_PAGE_ENABLE_LOADER && !GET_PARTNER_TOKEN_LOADER && !showLoader &&
        <ELearningWrapper>
          <img width='100%' src={ELEARNING_BACKGROUND} alt='' />
          <div className='content'>
            <p> {eLearningPara1} </p>
            <p> {eLearningListHead} </p>
            <ul>
              {
                eLearningList.map((litem, index) => (
                  <li key={index}> {litem} </li>
                ))
              }
            </ul>
            <p> {eLearningPara3} </p>
            <p> {LANG_STRINGS.haveGoodStudy} </p>
          </div>
          <BottomActionContainerStyle bottom='8vh' className='btn-container' direction='column'>
            <Row className='checkbox-container' align='center'>
              <CustomCheckbox
                isChecked={isCheckboxSelected}
                onChange={handleCheckbox}
              />
              <CustomText
                fontSize='10px'
                color={AgentColorPallette.regular}
              >
                {LANG_STRINGS.dontShowPageAgain}
              </CustomText>
            </Row>
            <ButtonWithIcon
              className='start-btn'
              text={LANG_STRINGS.courseStartContinue}
              icon={SEND_GOLD_ICON}
              iconRight
              onClick={handleCourseStart}
            />
          </BottomActionContainerStyle>
        </ELearningWrapper>}
    </Container>
  )
}

export default ElearningIntro
